  if (!finite(q?.value) || q.value <= 0 || !UNITS[q?.unit]) issues.push('Уточніть спожиту кількість');
  if (!finite(b?.value) || b.value <= 0 || !UNITS[b?.unit]) issues.push('Уточніть основу харчових значень');
